import sqlite3, datetime
con = sqlite3.connect('database.db')
cur = con.cursor()

for g in [1,2,3]:
    print(f'-- items_g{g} main_cat/store samples --')
    try:
        for row in cur.execute(f"SELECT main_cat, str_nm, COUNT(*) c FROM items_g{g} GROUP BY 1,2 ORDER BY c DESC LIMIT 10"):
            print(row)
    except Exception as e:
        print('ERR', e)
    print(f'-- items_g{g} price samples --')
    for row in cur.execute(f"SELECT ref_id, ttl, prc{', prc_usd' if g==2 else ''} FROM items_g{g} LIMIT 5"):
        print(row)
    print(f'-- feedback ts samples g{g} --')
    tbl=f'fdbk_g{g}'
    cols=[r[1] for r in cur.execute(f'PRAGMA table_info({tbl})')]
    tscol='ts'
    for row in cur.execute(f"SELECT {tscol} FROM {tbl} LIMIT 5"):
        print(row)
    print()
PY"}

