repeat_users AS (
  SELECT uid FROM mi_reviews WHERE uid IS NOT NULL GROUP BY uid HAVING COUNT(*)>=3
)
SELECT SUM(CASE WHEN m.rtg=5.0 THEN 1 ELSE 0 END), COUNT(*), ROUND(100.0*SUM(CASE WHEN m.rtg=5.0 THEN 1 ELSE 0 END)/COUNT(*),2)
FROM mi_reviews m JOIN repeat_users r ON m.uid=r.uid;
""}

