{"command": "sqlite3 database.db "
WITH office_items AS (
  SELECT ref_id FROM items_g1 WHERE main_cat='Office Products'
  UNION ALL SELECT ref_id FROM items_g2 WHERE main_cat='Office Products'
  UNION ALL SELECT ref_id FROM items_g3 WHERE main_cat='Office Products'
),
in_attrs AS (
  SELECT ref_id FROM attrs_g1
  UNION SELECT ref_id FROM attrs_g3
),
not_in_attrs AS (
  SELECT ref_id FROM office_items WHERE ref_id NOT IN (SELECT ref_id FROM in_attrs)
)
SELECT COUNT(*) FROM not_in_attrs;
""}

{"command": "sqlite3 database.db "
WITH office_items AS (
  SELECT ref_id FROM items_g1 WHERE main_cat='Office Products'
  UNION SELECT ref_id FROM items_g2 WHERE main_cat='Office Products'
  UNION SELECT ref_id FROM items_g3 WHERE main_cat='Office Products'
),
in_attrs AS (
  SELECT ref_id FROM attrs_g1 UNION SELECT ref_id FROM attrs_g3
),
not_in_attrs AS (
  SELECT ref_id FROM office_items WHERE ref_id NOT IN (SELECT ref_id FROM in_attrs)
),
with_reviews AS (
  SELECT DISTINCT ref_id FROM fdbk_g1
  UNION SELECT DISTINCT ref_id FROM fdbk_g2
  UNION SELECT DISTINCT ref_id FROM fdbk_g3
)
SELECT COUNT(*) FROM not_in_attrs WHERE ref_id IN (SELECT ref_id FROM with_reviews);
""}

